CREATE OR REPLACE FUNCTION public.can_read_homework_file(_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.homework_tasks t WHERE t.drill_media_path=_path AND public.can_read_team_homework(t.team_slug)) OR EXISTS(SELECT 1 FROM public.homework_questions q JOIN public.homework_tasks t ON t.id=q.task_id WHERE public.can_read_team_homework(t.team_slug) AND (q.scenario_media->>'photo'=_path OR EXISTS(SELECT 1 FROM jsonb_each_text(CASE WHEN jsonb_typeof(q.scenario_media->'videos')='object' THEN q.scenario_media->'videos' ELSE '{}'::jsonb END) v WHERE v.value=_path))) OR EXISTS(SELECT 1 FROM public.homework_submissions s JOIN public.homework_tasks t ON t.id=s.task_id WHERE s.proof_path=_path AND (s.user_id=auth.uid() OR public.can_manage_fitness(t.team_slug)))); $$;
REVOKE ALL ON FUNCTION public.can_read_homework_file(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_read_homework_file(text) TO authenticated,service_role;